const std = @import("std");
const mem = std.mem;
const Allocator = mem.Allocator;
const types = @import("../core/types.zig");
const Tensor = @import("../core/tensor.zig").Tensor;
const Error = types.Error;

pub const SSI = struct {
    root: ?*Node,
    allocator: Allocator,
    height: usize = 0,
    size: usize = 0,
    max_height: usize = bucket_width,

    pub const bucket_width: usize = 6;
    pub const bucket_count: usize = 1 << bucket_width;
    const tensor_metadata_width: usize = 8;
    const serialization_magic: u64 = 0x5353495F494E4458;
    const serialization_version: u32 = 2;

    pub const Segment = struct {
        tokens: []const u32,
        position: u64,
        score: f32,
        anchor_hash: u64,
        signature: u64,
        is_anchor: bool,

        pub fn init(allocator: Allocator, tokens: []const u32, position: u64, score: f32, anchor_hash: u64, is_anchor: bool) !Segment {
            const expected_anchor_hash = if (is_anchor) computeAnchorHash(tokens, position) else 0;
            if (anchor_hash != expected_anchor_hash) return error.InvalidData;
            return .{
                .tokens = try allocator.dupe(u32, tokens),
                .position = position,
                .score = score,
                .anchor_hash = anchor_hash,
                .signature = computeMinHashSignature(tokens),
                .is_anchor = is_anchor,
            };
        }

        pub fn deinit(self: *Segment, allocator: Allocator) void {
            allocator.free(self.tokens);
            self.tokens = &.{};
        }

        pub fn tokenHash(self: *const Segment) u64 {
            return hashTokens(self.tokens);
        }

        pub fn fullHash(self: *const Segment) u64 {
            var state: u64 = 0;
            state = mixHash(state, self.position);
            state = mixHash(state, @as(u64, scoreBits(self.score)));
            state = mixHash(state, self.anchor_hash);
            state = mixHash(state, self.signature);
            state = mixHash(state, if (self.is_anchor) 1 else 0);
            state = mixHash(state, @as(u64, @intCast(self.tokens.len)));
            for (self.tokens) |tok| {
                state = mixHash(state, tok);
            }
            return state;
        }
    };

    const CollisionNode = struct {
        seg: Segment,
        next: ?*CollisionNode,
    };

    const Node = struct {
        hash: u64,
        children: ?[]?*Node,
        segment: ?Segment,
        collision_chain: ?*CollisionNode,
        height: usize,
        is_leaf: bool,

        pub fn init(allocator: Allocator, node_height: usize) !Node {
            var children: ?[]?*Node = null;
            if (node_height > 0) {
                const allocated = try allocator.alloc(?*Node, bucket_count);
                @memset(allocated, null);
                children = allocated;
            }
            return .{
                .hash = 0,
                .children = children,
                .segment = null,
                .collision_chain = null,
                .height = node_height,
                .is_leaf = node_height == 0,
            };
        }

        pub fn deinit(self: *Node, allocator: Allocator) void {
            if (self.segment) |*seg| {
                seg.deinit(allocator);
                self.segment = null;
            }
            var chain = self.collision_chain;
            while (chain) |collision| {
                const next = collision.next;
                collision.seg.deinit(allocator);
                allocator.destroy(collision);
                chain = next;
            }
            self.collision_chain = null;
            if (self.children) |children| {
                allocator.free(children);
                self.children = null;
            }
        }
    };

    pub fn init(allocator: Allocator) SSI {
        return .{
            .root = null,
            .allocator = allocator,
            .height = 0,
            .size = 0,
            .max_height = bucket_width,
        };
    }

    pub fn mixHash(state: u64, value: u64) u64 {
        return state *% 0x9E3779B185EBCA87 +% value +% 0x517CC1B727220A95;
    }

    fn scoreBits(value: f32) u32 {
        return @as(u32, @bitCast(value));
    }

    pub fn hashTokens(tokens: []const u32) u64 {
        var state: u64 = 0;
        state = mixHash(state, @as(u64, @intCast(tokens.len)));
        for (tokens) |tok| {
            state = mixHash(state, tok);
        }
        return state;
    }

    fn minHashSeedA(lane: u64) u64 {
        return 0x9E3779B185EBCA87 +% lane *% 0xC2B2AE3D27D4EB4F +% 0x165667B19E3779F9;
    }

    fn minHashSeedB(lane: u64) u64 {
        return 0x517CC1B727220A95 +% lane *% 0xD6E8FEB86659FD93 +% 0x2545F4914F6CDD1D;
    }

    fn minHashLaneHash(token: u32, lane: u64) u64 {
        var hash = @as(u64, token) *% minHashSeedA(lane) +% minHashSeedB(lane);
        hash = (hash ^ (hash >> 30)) *% 0xbf58476d1ce4e5b9;
        hash = (hash ^ (hash >> 27)) *% 0x94d049bb133111eb;
        hash ^= hash >> 31;
        return hash;
    }

    pub fn computeMinHashSignature(tokens: []const u32) u64 {
        const vector_len: usize = 8;
        const lane_count: usize = 64 / vector_len;
        var minima: [lane_count]@Vector(vector_len, u64) = undefined;
        var lane: usize = 0;
        while (lane < lane_count) : (lane += 1) {
            minima[lane] = @splat(std.math.maxInt(u64));
        }
        for (tokens) |token| {
            lane = 0;
            while (lane < lane_count) : (lane += 1) {
                var hashes: @Vector(vector_len, u64) = undefined;
                var lane_bit: usize = 0;
                while (lane_bit < vector_len) : (lane_bit += 1) {
                    hashes[lane_bit] = minHashLaneHash(token, @as(u64, @intCast(lane * vector_len + lane_bit)));
                }
                minima[lane] = @min(minima[lane], hashes);
            }
        }
        var signature: u64 = 0;
        lane = 0;
        while (lane < lane_count) : (lane += 1) {
            const parities = minima[lane] & @as(@Vector(vector_len, u64), @splat(1));
            var lane_bit: usize = 0;
            while (lane_bit < vector_len) : (lane_bit += 1) {
                if (parities[lane_bit] != 0) {
                    signature |= @as(u64, 1) << @intCast(lane * vector_len + lane_bit);
                }
            }
        }
        return signature;
    }

    pub fn signatureSimilarity(query_signature: u64, segment_signature: u64) f32 {
        const mismatch = @popCount(query_signature ^ segment_signature);
        const matches = 64 - @as(i64, @intCast(mismatch));
        if (matches <= 0) return 0.0;
        const ratio = @as(f32, @floatFromInt(matches)) / 64.0;
        const estimate = 2.0 * ratio - 1.0;
        return std.math.clamp(estimate, @as(f32, 0.0), @as(f32, 1.0));
    }

    pub fn computeAnchorHash(tokens: []const u32, position: u64) u64 {
        var state: u64 = position;
        state = mixHash(state, @as(u64, @intCast(tokens.len)));
        for (tokens) |tok| {
            state = mixHash(state, tok);
        }
        return state;
    }

    pub fn bucketIndex(position: u64) usize {
        var hash = position *% 0x9E3779B185EBCA87;
        hash = (hash ^ (hash >> 30)) *% 0xbf58476d1ce4e5b9;
        hash = (hash ^ (hash >> 27)) *% 0x94d049bb133111eb;
        hash ^= hash >> 31;
        return @as(usize, @intCast(hash & (bucket_count - 1)));
    }

    fn low32(value: u64) u32 {
        return @as(u32, @intCast(value & 0xFFFF_FFFF));
    }

    fn high32(value: u64) u32 {
        return @as(u32, @intCast(value >> 32));
    }

    fn joinU64(lo: u32, hi: u32) u64 {
        return (@as(u64, hi) << 32) | @as(u64, lo);
    }

    fn bitsToFloat(bits: u32) f32 {
        return @as(f32, @bitCast(bits));
    }

    fn floatToBits(value: f32) u32 {
        return @as(u32, @bitCast(value));
    }

    fn createNode(allocator: Allocator, node_height: usize) !*Node {
        const node = try allocator.create(Node);
        errdefer allocator.destroy(node);
        node.* = try Node.init(allocator, node_height);
        return node;
    }

    fn recursiveDeinit(node: *Node, allocator: Allocator) void {
        if (node.children) |children| {
            for (children) |maybe_child| {
                if (maybe_child) |child| {
                    recursiveDeinit(child, allocator);
                }
            }
        }
        node.deinit(allocator);
        allocator.destroy(node);
    }

    pub fn deinit(self: *SSI) void {
        if (self.root) |root| {
            recursiveDeinit(root, self.allocator);
        }
        self.root = null;
        self.height = 0;
        self.size = 0;
    }

    fn computeLeafHash(node: *const Node) u64 {
        var accumulator: u64 = 0;
        if (node.segment) |seg| {
            accumulator +%= seg.fullHash();
        }
        var chain = node.collision_chain;
        while (chain) |collision| {
            accumulator +%= collision.seg.fullHash();
            chain = collision.next;
        }
        return accumulator;
    }

    fn computeBranchHash(node: *const Node) u64 {
        var accumulator: u64 = 0;
        if (node.children) |children| {
            for (children) |maybe_child| {
                if (maybe_child) |child| {
                    accumulator +%= child.hash;
                }
            }
        }
        return accumulator;
    }

    fn refreshHash(node: *Node) void {
        node.hash = if (node.is_leaf) computeLeafHash(node) else computeBranchHash(node);
    }

    fn ensureRoot(self: *SSI) !*Node {
        if (self.max_height != bucket_width) return error.InvalidNodeState;
        if (self.root == null) {
            const root = try createNode(self.allocator, self.max_height);
            refreshHash(root);
            self.root = root;
            self.height = self.max_height;
        }
        const root = self.root.?;
        if (root.is_leaf or root.height != self.max_height or root.children == null) return error.InvalidNodeState;
        return root;
    }

    fn insertIntoLeaf(self: *SSI, leaf: *Node, tokens: []const u32, position: u64, score: f32, anchor_hash: u64, is_anchor: bool) !bool {
        if (!leaf.is_leaf or leaf.height != 0 or leaf.children != null) return error.InvalidNodeState;
        if (leaf.segment == null) {
            if (leaf.collision_chain != null) return error.InvalidNodeState;
            leaf.segment = try Segment.init(self.allocator, tokens, position, score, anchor_hash, is_anchor);
            refreshHash(leaf);
            return true;
        }
        if (leaf.segment.?.position == position) {
            var replacement = try Segment.init(self.allocator, tokens, position, score, anchor_hash, is_anchor);
            var old = leaf.segment.?;
            leaf.segment = replacement;
            replacement.tokens = &.{};
            old.deinit(self.allocator);
            refreshHash(leaf);
            return false;
        }
        var chain = leaf.collision_chain;
        while (chain) |collision| {
            if (collision.seg.position == position) {
                var replacement = try Segment.init(self.allocator, tokens, position, score, anchor_hash, is_anchor);
                var old = collision.seg;
                collision.seg = replacement;
                replacement.tokens = &.{};
                old.deinit(self.allocator);
                refreshHash(leaf);
                return false;
            }
            chain = collision.next;
        }
        var segment = try Segment.init(self.allocator, tokens, position, score, anchor_hash, is_anchor);
        errdefer segment.deinit(self.allocator);
        const collision = try self.allocator.create(CollisionNode);
        collision.* = .{
            .seg = segment,
            .next = leaf.collision_chain,
        };
        leaf.collision_chain = collision;
        refreshHash(leaf);
        return true;
    }

    fn addSequenceWithMetadata(self: *SSI, tokens: []const u32, position: u64, score: f32, anchor_hash: u64, is_anchor: bool) !void {
        if (self.size == std.math.maxInt(usize)) return error.OutOfMemory;
        const expected_anchor_hash = if (is_anchor) computeAnchorHash(tokens, position) else 0;
        if (anchor_hash != expected_anchor_hash) return error.InvalidData;
        const root = try self.ensureRoot();
        const index = bucketIndex(position);
        if (root.children.?[index] == null) {
            const leaf = try createNode(self.allocator, 0);
            errdefer recursiveDeinit(leaf, self.allocator);
            const inserted_new = try self.insertIntoLeaf(leaf, tokens, position, score, anchor_hash, is_anchor);
            if (!inserted_new) return error.InvalidNodeState;
            root.children.?[index] = leaf;
            self.size += 1;
            refreshHash(root);
            return;
        }
        const leaf = root.children.?[index].?;
        const inserted_new = try self.insertIntoLeaf(leaf, tokens, position, score, anchor_hash, is_anchor);
        if (inserted_new) self.size += 1;
        refreshHash(root);
    }

    fn copyNodeInto(node: *const Node, target: *SSI) !void {
        if (node.is_leaf) {
            if (node.segment) |seg| {
                try target.addSequenceWithMetadata(seg.tokens, seg.position, seg.score, seg.anchor_hash, seg.is_anchor);
            }
            var chain = node.collision_chain;
            while (chain) |collision| {
                const seg = collision.seg;
                try target.addSequenceWithMetadata(seg.tokens, seg.position, seg.score, seg.anchor_hash, seg.is_anchor);
                chain = collision.next;
            }
            return;
        }
        const children = node.children orelse return error.InvalidNodeState;
        for (children) |maybe_child| {
            if (maybe_child) |child| {
                try copyNodeInto(child, target);
            }
        }
    }

    fn copyInto(self: *const SSI, target: *SSI) !void {
        if (self.root) |root| {
            try copyNodeInto(root, target);
        }
    }

    pub fn addSequence(self: *SSI, tokens: []const u32, position: u64, is_anchor: bool) !void {
        const anchor_hash = if (is_anchor) computeAnchorHash(tokens, position) else 0;
        try self.addSequenceWithMetadata(tokens, position, 0.0, anchor_hash, is_anchor);
    }

    pub fn retrieveTopK(self: *const SSI, query_tokens: []const u32, k: usize, allocator: Allocator) ![]types.RankedSegment {
        if (k == 0) return allocator.alloc(types.RankedSegment, 0);
        var heap = std.PriorityQueue(types.RankedSegment, void, struct {
            pub fn lessThan(_: void, a: types.RankedSegment, b: types.RankedSegment) std.math.Order {
                return std.math.order(a.score, b.score);
            }
        }.lessThan).init(allocator, {});
        defer heap.deinit();
        errdefer {
            while (heap.removeOrNull()) |item| {
                var mutable_item = item;
                mutable_item.deinit(allocator);
            }
        }
        const query_hash = hashTokens(query_tokens);
        const query_signature = computeMinHashSignature(query_tokens);
        try self.traverse(self.root, query_hash, query_signature, &heap, k, allocator);
        const result_len = @min(k, heap.count());
        const top_n = try allocator.alloc(types.RankedSegment, result_len);
        var index = result_len;
        while (heap.removeOrNull()) |item| {
            index -= 1;
            top_n[index] = item;
        }
        return top_n;
    }

    fn traverse(self: *const SSI, node: ?*Node, query_hash: u64, query_signature: u64, heap: anytype, k: usize, allocator: Allocator) !void {
        const current = node orelse return;
        if (current.is_leaf) {
            if (current.segment) |seg| {
                try addSegmentToHeap(seg, query_hash, query_signature, heap, k, allocator);
            }
            var chain = current.collision_chain;
            while (chain) |collision| {
                try addSegmentToHeap(collision.seg, query_hash, query_signature, heap, k, allocator);
                chain = collision.next;
            }
            return;
        }
        const children = current.children orelse return error.InvalidNodeState;
        for (children) |maybe_child| {
            if (maybe_child) |child| {
                try traverse(self, child, query_hash, query_signature, heap, k, allocator);
            }
        }
    }

    fn addSegmentToHeap(seg: Segment, query_hash: u64, query_signature: u64, heap: anytype, k: usize, allocator: Allocator) !void {
        const similarity = computeFusedSimilarity(query_hash, query_signature, seg.tokenHash(), seg.signature);
        if (heap.count() >= k) {
            if (heap.peek()) |top| {
                if (similarity <= top.score) return;
            }
        }
        const ranked = types.RankedSegment{
            .tokens = try allocator.dupe(u32, seg.tokens),
            .score = similarity,
            .position = seg.position,
            .anchor = seg.is_anchor,
        };
        errdefer allocator.free(ranked.tokens);
        if (heap.count() < k) {
            try heap.add(ranked);
            return;
        }
        try heap.add(ranked);
        var removed = heap.remove();
        removed.deinit(allocator);
    }

    fn computeSimilarity(hash_a: u64, hash_b: u64) f32 {
        const population_a = @popCount(hash_a);
        const population_b = @popCount(hash_b);
        if (population_a == 0 and population_b == 0) return 1.0;
        if (population_a == 0 or population_b == 0) return 0.0;
        const intersection = @popCount(hash_a & hash_b);
        const denominator = @sqrt(@as(f32, @floatFromInt(population_a)) * @as(f32, @floatFromInt(population_b)));
        return @as(f32, @floatFromInt(intersection)) / denominator;
    }

    fn computeFusedSimilarity(query_hash: u64, query_signature: u64, segment_hash: u64, segment_signature: u64) f32 {
        const hash_cosine = computeSimilarity(query_hash, segment_hash);
        const jaccard_estimate = signatureSimilarity(query_signature, segment_signature);
        return 0.5 * hash_cosine + 0.5 * jaccard_estimate;
    }

    fn replaceWith(self: *SSI, replacement: *SSI) void {
        const old_root = self.root;
        const old_height = self.height;
        const old_size = self.size;
        const old_max_height = self.max_height;
        self.root = replacement.root;
        self.height = replacement.height;
        self.size = replacement.size;
        self.max_height = replacement.max_height;
        replacement.root = old_root;
        replacement.height = old_height;
        replacement.size = old_size;
        replacement.max_height = old_max_height;
        replacement.deinit();
    }

    pub fn compact(self: *SSI) !void {
        var rebuilt = SSI.init(self.allocator);
        rebuilt.max_height = self.max_height;
        errdefer rebuilt.deinit();
        try self.copyInto(&rebuilt);
        self.replaceWith(&rebuilt);
    }

    pub fn updateScore(self: *SSI, position: u64, new_score: f32) !void {
        const root = self.root orelse return Error.OutOfBounds;
        if (root.is_leaf) return error.InvalidNodeState;
        const children = root.children orelse return error.InvalidNodeState;
        const child = children[bucketIndex(position)] orelse return Error.OutOfBounds;
        if (child.segment) |*seg| {
            if (seg.position == position) {
                seg.score = new_score;
                refreshHash(child);
                refreshHash(root);
                return;
            }
        }
        var chain = child.collision_chain;
        while (chain) |collision| {
            if (collision.seg.position == position) {
                collision.seg.score = new_score;
                refreshHash(child);
                refreshHash(root);
                return;
            }
            chain = collision.next;
        }
        return Error.OutOfBounds;
    }

    pub fn getSegment(self: *const SSI, position: u64) ?*const Segment {
        const root = self.root orelse return null;
        if (root.is_leaf) return null;
        const children = root.children orelse return null;
        const child = children[bucketIndex(position)] orelse return null;
        if (child.segment) |*seg| {
            if (seg.position == position) return seg;
        }
        var chain = child.collision_chain;
        while (chain) |collision| {
            if (collision.seg.position == position) return &collision.seg;
            chain = collision.next;
        }
        return null;
    }

    fn countNodeSegments(node: *const Node) usize {
        if (node.is_leaf) {
            var count: usize = if (node.segment == null) 0 else 1;
            var chain = node.collision_chain;
            while (chain) |collision| {
                count += 1;
                chain = collision.next;
            }
            return count;
        }
        var count: usize = 0;
        if (node.children) |children| {
            for (children) |maybe_child| {
                if (maybe_child) |child| count += countNodeSegments(child);
            }
        }
        return count;
    }

    fn countSegments(self: *const SSI) usize {
        const root = self.root orelse return 0;
        return countNodeSegments(root);
    }

    fn writeBoolFlag(writer: anytype, value: bool) !void {
        try writer.writeInt(u8, if (value) 1 else 0, .little);
    }

    fn readBoolFlag(reader: anytype) !bool {
        return switch (try reader.readInt(u8, .little)) {
            0 => false,
            1 => true,
            else => error.InvalidData,
        };
    }

    fn writeUsize(writer: anytype, value: usize) !void {
        if (value > std.math.maxInt(u64)) return error.InvalidData;
        try writer.writeInt(u64, @as(u64, @intCast(value)), .little);
    }

    fn readUsize(reader: anytype) !usize {
        const value = try reader.readInt(u64, .little);
        if (value > std.math.maxInt(usize)) return error.InvalidData;
        return @as(usize, @intCast(value));
    }

    fn writeSegment(writer: anytype, seg: Segment) !void {
        try writer.writeInt(u64, seg.position, .little);
        try writer.writeInt(u32, floatToBits(seg.score), .little);
        try writer.writeInt(u64, seg.anchor_hash, .little);
        try writer.writeInt(u64, seg.signature, .little);
        try writeBoolFlag(writer, seg.is_anchor);
        try writeUsize(writer, seg.tokens.len);
        for (seg.tokens) |token| {
            try writer.writeInt(u32, token, .little);
        }
    }

    fn readSegment(allocator: Allocator, reader: anytype) !Segment {
        const position = try reader.readInt(u64, .little);
        const score = bitsToFloat(try reader.readInt(u32, .little));
        const anchor_hash = try reader.readInt(u64, .little);
        const stored_signature = try reader.readInt(u64, .little);
        const is_anchor = try readBoolFlag(reader);
        const token_len = try readUsize(reader);
        const tokens = try allocator.alloc(u32, token_len);
        errdefer allocator.free(tokens);
        for (tokens) |*token| {
            token.* = try reader.readInt(u32, .little);
        }
        const signature = computeMinHashSignature(tokens);
        if (signature != stored_signature) return error.InvalidData;
        const expected_anchor_hash = if (is_anchor) computeAnchorHash(tokens, position) else 0;
        if (anchor_hash != expected_anchor_hash) return error.InvalidData;
        return .{
            .tokens = tokens,
            .position = position,
            .score = score,
            .anchor_hash = anchor_hash,
            .signature = signature,
            .is_anchor = is_anchor,
        };
    }

    fn readCollision(allocator: Allocator, reader: anytype) !*CollisionNode {
        const collision = try allocator.create(CollisionNode);
        errdefer allocator.destroy(collision);
        collision.* = .{
            .seg = try readSegment(allocator, reader),
            .next = null,
        };
        return collision;
    }

    fn serializeNode(node: *const Node, writer: anytype) !void {
        try writeBoolFlag(writer, node.is_leaf);
        try writeUsize(writer, node.height);
        try writer.writeInt(u64, node.hash, .little);
        if (node.is_leaf) {
            try writeBoolFlag(writer, node.segment != null);
            if (node.segment) |seg| try writeSegment(writer, seg);
            var chain_len: usize = 0;
            var chain = node.collision_chain;
            while (chain) |collision| {
                chain_len += 1;
                chain = collision.next;
            }
            try writeUsize(writer, chain_len);
            chain = node.collision_chain;
            while (chain) |collision| {
                try writeSegment(writer, collision.seg);
                chain = collision.next;
            }
            return;
        }
        const children = node.children orelse return error.InvalidNodeState;
        try writeUsize(writer, children.len);
        for (children) |maybe_child| {
            try writeBoolFlag(writer, maybe_child != null);
            if (maybe_child) |child| try serializeNode(child, writer);
        }
    }

    fn deserializeNode(allocator: Allocator, reader: anytype, expected_leaf: bool, expected_height: usize) !*Node {
        const is_leaf = try readBoolFlag(reader);
        const node_height = try readUsize(reader);
        const stored_hash = try reader.readInt(u64, .little);
        if (is_leaf != expected_leaf or node_height != expected_height) return error.InvalidData;
        const node = try createNode(allocator, node_height);
        errdefer recursiveDeinit(node, allocator);
        if (is_leaf) {
            const has_segment = try readBoolFlag(reader);
            if (!has_segment) return error.InvalidData;
            node.segment = try readSegment(allocator, reader);
            const chain_len = try readUsize(reader);
            var tail: ?*CollisionNode = null;
            var index: usize = 0;
            while (index < chain_len) : (index += 1) {
                const collision = try readCollision(allocator, reader);
                if (tail) |current_tail| {
                    current_tail.next = collision;
                } else {
                    node.collision_chain = collision;
                }
                tail = collision;
            }
        } else {
            const children_len = try readUsize(reader);
            if (children_len != bucket_count) return error.InvalidData;
            var index: usize = 0;
            while (index < children_len) : (index += 1) {
                if (try readBoolFlag(reader)) {
                    node.children.?[index] = try deserializeNode(allocator, reader, true, 0);
                }
            }
        }
        refreshHash(node);
        if (node.hash != stored_hash) return error.InvalidData;
        return node;
    }

    pub fn serialize(self: *const SSI, writer: anytype) !void {
        if (!(try self.validateInternal())) return error.InvalidData;
        try writer.writeInt(u64, serialization_magic, .little);
        try writer.writeInt(u32, serialization_version, .little);
        try writeUsize(writer, self.max_height);
        try writeUsize(writer, self.height);
        try writeUsize(writer, self.size);
        try writeBoolFlag(writer, self.root != null);
        if (self.root) |root| try serializeNode(root, writer);
    }

    pub fn deserialize(allocator: Allocator, reader: anytype) !SSI {
        if (try reader.readInt(u64, .little) != serialization_magic) return error.InvalidData;
        if (try reader.readInt(u32, .little) != serialization_version) return error.InvalidData;
        var ssi = SSI.init(allocator);
        errdefer ssi.deinit();
        ssi.max_height = try readUsize(reader);
        ssi.height = try readUsize(reader);
        ssi.size = try readUsize(reader);
        if (ssi.max_height != bucket_width) return error.InvalidData;
        const has_root = try readBoolFlag(reader);
        if (has_root) {
            if (ssi.height != ssi.max_height) return error.InvalidData;
            ssi.root = try deserializeNode(allocator, reader, false, ssi.max_height);
        } else if (ssi.height != 0 or ssi.size != 0) {
            return error.InvalidData;
        }
        if (!(try ssi.validateInternal())) return error.InvalidData;
        return ssi;
    }

    fn maxNodeTokenLength(node: *const Node) usize {
        if (node.is_leaf) {
            var maximum: usize = 0;
            if (node.segment) |seg| maximum = seg.tokens.len;
            var chain = node.collision_chain;
            while (chain) |collision| {
                maximum = @max(maximum, collision.seg.tokens.len);
                chain = collision.next;
            }
            return maximum;
        }
        var maximum: usize = 0;
        if (node.children) |children| {
            for (children) |maybe_child| {
                if (maybe_child) |child| maximum = @max(maximum, maxNodeTokenLength(child));
            }
        }
        return maximum;
    }

    fn encodeSegmentRow(tensor: *Tensor, width: usize, row: usize, seg: Segment) void {
        const offset = row * width;
        const token_len: u64 = @intCast(seg.tokens.len);
        tensor.data[offset + 0] = bitsToFloat(low32(token_len));
        tensor.data[offset + 1] = bitsToFloat(high32(token_len));
        tensor.data[offset + 2] = bitsToFloat(low32(seg.position));
        tensor.data[offset + 3] = bitsToFloat(high32(seg.position));
        tensor.data[offset + 4] = seg.score;
        tensor.data[offset + 5] = bitsToFloat(low32(seg.anchor_hash));
        tensor.data[offset + 6] = bitsToFloat(high32(seg.anchor_hash));
        tensor.data[offset + 7] = if (seg.is_anchor) 1.0 else 0.0;
        for (seg.tokens, 0..) |token, index| {
            tensor.data[offset + tensor_metadata_width + index] = bitsToFloat(token);
        }
    }

    fn encodeNodeRows(node: *const Node, tensor: *Tensor, width: usize, row: *usize) void {
        if (node.is_leaf) {
            if (node.segment) |seg| {
                encodeSegmentRow(tensor, width, row.*, seg);
                row.* += 1;
            }
            var chain = node.collision_chain;
            while (chain) |collision| {
                encodeSegmentRow(tensor, width, row.*, collision.seg);
                row.* += 1;
                chain = collision.next;
            }
            return;
        }
        if (node.children) |children| {
            for (children) |maybe_child| {
                if (maybe_child) |child| encodeNodeRows(child, tensor, width, row);
            }
        }
    }

    pub fn exportToTensor(self: *const SSI, allocator: Allocator) !Tensor {
        if (!(try self.validateInternal())) return error.InvalidData;
        const segment_count = self.countSegments();
        const max_tokens = if (self.root) |root| maxNodeTokenLength(root) else 0;
        if (max_tokens > std.math.maxInt(u64)) return error.InvalidData;
        if (max_tokens > std.math.maxInt(usize) - tensor_metadata_width) return error.InvalidData;
        const width = tensor_metadata_width + max_tokens;
        if (segment_count != 0 and width > std.math.maxInt(usize) / segment_count) return error.InvalidData;
        var tensor = try Tensor.init(allocator, &.{ segment_count, width });
        @memset(tensor.data, 0);
        var row: usize = 0;
        if (self.root) |root| encodeNodeRows(root, &tensor, width, &row);
        return tensor;
    }

    pub fn importFromTensor(self: *SSI, tensor: *const Tensor) !void {
        if (tensor.shape.dims.len != 2) return error.InvalidData;
        const rows = tensor.shape.dims[0];
        const width = tensor.shape.dims[1];
        if (width < tensor_metadata_width) return error.InvalidData;
        if (rows != 0 and width > std.math.maxInt(usize) / rows) return error.InvalidData;
        if (tensor.data.len != rows * width) return error.InvalidData;
        var rebuilt = SSI.init(self.allocator);
        errdefer rebuilt.deinit();
        var row: usize = 0;
        while (row < rows) : (row += 1) {
            const offset = row * width;
            const token_len_u64 = joinU64(floatToBits(tensor.data[offset + 0]), floatToBits(tensor.data[offset + 1]));
            if (token_len_u64 > std.math.maxInt(usize)) return error.InvalidData;
            const token_len: usize = @intCast(token_len_u64);
            if (token_len > width - tensor_metadata_width) return error.InvalidData;
            const position = joinU64(floatToBits(tensor.data[offset + 2]), floatToBits(tensor.data[offset + 3]));
            const score = tensor.data[offset + 4];
            const anchor_hash = joinU64(floatToBits(tensor.data[offset + 5]), floatToBits(tensor.data[offset + 6]));
            const anchor_flag = tensor.data[offset + 7];
            const is_anchor = if (anchor_flag == 0.0) false else if (anchor_flag == 1.0) true else return error.InvalidData;
            const tokens = try self.allocator.alloc(u32, token_len);
            defer self.allocator.free(tokens);
            for (tokens, 0..) |*token, index| {
                token.* = floatToBits(tensor.data[offset + tensor_metadata_width + index]);
            }
            const expected_anchor_hash = if (is_anchor) computeAnchorHash(tokens, position) else 0;
            if (anchor_hash != expected_anchor_hash) return error.InvalidData;
            if (rebuilt.getSegment(position) != null) return error.InvalidData;
            try rebuilt.addSequenceWithMetadata(tokens, position, score, anchor_hash, is_anchor);
        }
        self.replaceWith(&rebuilt);
    }

    pub fn merge(self: *SSI, other: *const SSI) !void {
        if (@intFromPtr(self) == @intFromPtr(other)) return;
        var rebuilt = SSI.init(self.allocator);
        errdefer rebuilt.deinit();
        try self.copyInto(&rebuilt);
        try other.copyInto(&rebuilt);
        self.replaceWith(&rebuilt);
    }

    pub fn split(self: *const SSI, threshold: f32) !SSI {
        var result = SSI.init(self.allocator);
        errdefer result.deinit();
        if (self.root) |root| try splitNodeInto(root, threshold, &result);
        return result;
    }

    fn splitNodeInto(node: *const Node, threshold: f32, result: *SSI) !void {
        if (node.is_leaf) {
            if (node.segment) |seg| {
                if (seg.score > threshold) try result.addSequenceWithMetadata(seg.tokens, seg.position, seg.score, seg.anchor_hash, seg.is_anchor);
            }
            var chain = node.collision_chain;
            while (chain) |collision| {
                const seg = collision.seg;
                if (seg.score > threshold) try result.addSequenceWithMetadata(seg.tokens, seg.position, seg.score, seg.anchor_hash, seg.is_anchor);
                chain = collision.next;
            }
            return;
        }
        const children = node.children orelse return error.InvalidNodeState;
        for (children) |maybe_child| {
            if (maybe_child) |child| try splitNodeInto(child, threshold, result);
        }
    }

    pub fn balance(self: *SSI) !void {
        try self.compact();
    }

    fn accumulateStats(node: *const Node, current_depth: usize, nodes: *usize, leaves: *usize, depth: *usize) void {
        nodes.* += 1;
        depth.* = @max(depth.*, current_depth);
        if (node.is_leaf) {
            leaves.* += 1;
            return;
        }
        if (node.children) |children| {
            for (children) |maybe_child| {
                if (maybe_child) |child| accumulateStats(child, current_depth + 1, nodes, leaves, depth);
            }
        }
    }

    pub fn stats(self: *const SSI) struct { nodes: usize, leaves: usize, depth: usize } {
        var nodes: usize = 0;
        var leaves: usize = 0;
        var depth: usize = 0;
        if (self.root) |root| accumulateStats(root, 0, &nodes, &leaves, &depth);
        return .{ .nodes = nodes, .leaves = leaves, .depth = depth };
    }

    fn validateSegment(seg: Segment) bool {
        if (seg.signature != computeMinHashSignature(seg.tokens)) return false;
        const expected_anchor_hash = if (seg.is_anchor) computeAnchorHash(seg.tokens, seg.position) else 0;
        return seg.anchor_hash == expected_anchor_hash;
    }

    fn validateLeaf(node: *const Node, expected_bucket: usize, position_set: anytype) !bool {
        if (!node.is_leaf or node.height != 0 or node.children != null) return false;
        const primary = node.segment orelse return false;
        if (!validateSegment(primary) or bucketIndex(primary.position) != expected_bucket) return false;
        if (position_set.contains(primary.position)) return false;
        try position_set.put(primary.position, {});
        var chain = node.collision_chain;
        while (chain) |collision| {
            if (!validateSegment(collision.seg) or bucketIndex(collision.seg.position) != expected_bucket) return false;
            if (position_set.contains(collision.seg.position)) return false;
            try position_set.put(collision.seg.position, {});
            chain = collision.next;
        }
        return computeLeafHash(node) == node.hash;
    }

    fn validateInternal(self: *const SSI) !bool {
        if (self.max_height != bucket_width) return false;
        const root = self.root orelse return self.size == 0 and self.height == 0;
        if (root.is_leaf or self.height != self.max_height or root.height != self.max_height) return false;
        const children = root.children orelse return false;
        if (children.len != bucket_count or root.segment != null or root.collision_chain != null) return false;
        var position_set = std.AutoHashMap(u64, void).init(self.allocator);
        defer position_set.deinit();
        var accumulator: u64 = 0;
        for (children, 0..) |maybe_child, index| {
            if (maybe_child) |child| {
                if (!(try validateLeaf(child, index, &position_set))) return false;
                accumulator +%= child.hash;
            }
        }
        if (accumulator != root.hash) return false;
        return position_set.count() == self.size;
    }

    pub fn validate(self: *const SSI) bool {
        return self.validateInternal() catch false;
    }
};
